#define FJ_RECIPE_TYPE(t) sizeof(t), _Alignof(t),
#define FJ_RECIPE_FIELD(t, f) offsetof(t, f),
#define FJ_RECIPE_EXTENT(t, f, e) sizeof(((t*)0)->f) / sizeof(e),
